/* DAVYLAB WORLD/TOON | v1.0 | Local-first creative studio. No hidden server uploads. */
'use strict';
const APP_KEY='davylab-comic-press-v1', DB_NAME='davylab-comic-media-v1', LEGACY_KEY='davylab_worldtoon_v01';
const assetNames=['01_甜蜜暗流.png','02_执法突袭.png','03_寻找靠山.png','04_选举失势.png','05_公开恋情.png','06_发布会.png','07_茶话风云.png','08_撕碎人设.png','09_最后的选择.png'];
const stages=['选题与来源','改编设定','分镜脚本','画面制作','审核与出版'];
const checksText=['已区分可核验事实、观点、传闻与虚构','已核查至少一条有效的原始事件来源','改编不会通过独特细节对号入座真实自然人','没有将未经证实的违法、婚恋或交易指控写成事实','图片素材有合法使用权，人物形象和台词已复核','漫画明确标注虚构改编，完成逐格人工审校'];
const now=()=>new Date().toISOString();
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'cp-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml, safeURL=(u)=>{try{let v=new URL(u);return ['https:','http:'].includes(v.protocol)?v.href:''}catch{return ''}};
const humanDate=s=>s?new Date(s).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}):'—';
const safeName=s=>(s||'comic').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,70);
const CATS=['国际政治','文化','娱乐','体育','人物','旅行','AI 科技','机器人','商业财经','科学','环境','健康','航空航天','其他'];
const prompts=[
['甜蜜暗流','芯片霸总与神秘女友亲密相拥。远方鹰与兔代表两方势力对峙。','霸总爱情甜如蜜，鹰兔博弈暗流急。',''],
['执法突袭','虚构执法人员闯入，女友被带走，霸总震惊。','风暴来得比新闻推送还快。','执法人员：你涉嫌间谍罪！'],
['秘密游说','霸总深夜拜访政客，办公室里光影交错。','面对困局，他试着寻找权力靠山。','霸总：只要选举顺利，这件事能办吧？'],
['选举失势','电视屏幕出现虚构选举结果，政客神色低沉。','选举翻车，靠山塌了。',''],
['破釜沉舟','霸总拍桌，桌上的棋子翻倒。','最后一张牌，居然是爱情。','霸总：公开我们的关系！'],
['公开恋情','新闻发布会，闪光灯下两人站在一起。','是爱情，也是舆论风暴。','霸总：是的，我们相爱。'],
['圈内茶话','虚构商业精英在茶室低声议论，窗外鹰兔棋盘悬浮。','在资本叙事里，爱情从来不只是爱情。',''],
['撕碎人设','霸总撕掉写有“爱妻人设”的纸张。','当人设碎裂，真相也未必浮现。','霸总：这一次，我自己选。'],
['最后一幕','夕阳下两人走向飞机，画面留白。','这场小爱情，是一则关于权力、资本与叙事的虚构寓言。','']
];
function makePanel(i,seed=false){let p=prompts[i];return {id:uid(),title:seed?p[0]:`第 ${i+1} 格`,scene:seed?p[1]:'',caption:seed?p[2]:'',dialogue:seed?p[3]:'',prompt:'',image:seed?`assets/${assetNames[i]}`:''}}
function sampleProject(){let t=now();return {id:'sample-ba-zong-001',title:'霸总的小爱情',subtitle:'爱情与权力的九格寓言',description:'虚构的芯片霸总与神秘女友，卷入由舆论、政治与商业交织而成的风暴。',category:'商业财经',tone:'黑色幽默',format:'九格短篇',status:'示例',archived:false,deleted:false,createdAt:t,updatedAt:t,sourceTitle:'跨国科技与政治风波（虚构主题）',sourceURLs:'',eventDate:'',factNotes:'这是原创虚构演示故事，不代表对某一真实案件的核验或报道。',fiction:'人物、国家符号、人物间交易、关系及情节均为虚构；避免推断到真实个人。',characters:'芯片霸总／神秘女友／虚构政客／虚构执法人员／鹰兔象征',disclosure:'本故事纯属虚构，不应据此推断任何现实人物违法、私人关系或政治交易。',panels:prompts.map((_,i)=>makePanel(i,true)),checks:Array(6).fill(false),activity:[{at:t,detail:'内置示例作品已建立'}],reviewedAt:null,publishedAt:null,cover:'assets/cover.png'};}
function emptyProject(topic){let t=now();let p={id:uid(),title:topic?.title?`${topic.title}：漫画改编`:'未命名新作',subtitle:'',description:topic?.summary||'',category:topic?.category||'AI 科技',tone:'黑色幽默',format:'九格短篇',status:'草稿',archived:false,deleted:false,createdAt:t,updatedAt:t,sourceTitle:topic?.title||'',sourceURLs:topic?.source||'',eventDate:'',factNotes:'',fiction:'',characters:'',disclosure:'本作品是基于公共议题创作的虚构漫画，不构成对真实人物的指控。',panels:Array.from({length:9},(_,i)=>makePanel(i)),checks:Array(6).fill(false),activity:[{at:t,detail:'创建草稿'}],reviewedAt:null,publishedAt:null,cover:''};return p}
const sampleTopic={id:'sample-topic-001',title:'科技产业与国际政治的戏剧性碰撞',category:'商业财经',summary:'仅用于展示选题结构；不是实时新闻，也未完成事实核验。',source:'',heat:3,impact:4,story:5,stage:'待核验',isSample:true,createdAt:now()};
const initial=()=>({version:3,projects:[sampleProject()],topics:[sampleTopic],characters:[],settings:{brand:'By DAVYLAB',color:'#df624a'},logs:[]});
let legacyImport=false;
function importLegacyMetadata(){
 try{
  const old=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');
  if(!Array.isArray(old)||!old.length)return null;
  const imported=old.filter(x=>x&&typeof x==='object').map((o,index)=>{
   let p=emptyProject();p.id=`legacy-${String(o.id||index).replace(/[^a-zA-Z0-9_-]/g,'-')}`;
   p.title=String(o.title||`旧版作品 ${index+1}`);p.subtitle='从 WORLD/TOON V0.1 导入';p.description=String(o.notes||'');p.category='国际政治';p.tone=String(o.style||'黑色幽默');p.status=['已发布','已审核','待审核'].includes(o.stage)?o.stage:'草稿';p.sourceTitle=p.title;p.sourceURLs=String(o.source||'');p.factNotes=String(o.notes||'');p.fiction='旧版导入：请补充独立人物世界观与脱敏策略。';p.disclosure='原创虚构漫画，不代表真实事件报道。请完成来源、内容与授权审查后再发布。';p.panels=Array.from({length:9},(_,i)=>{let a=o.panels?.[i]||{};return {...makePanel(i),scene:String(a.scene||''),dialogue:String(a.dialogue||''),image:String(a.image||'')}});p.checks=Array(6).fill(false);p.reviewedAt=null;p.publishedAt=null;if(p.status!=='草稿')p.status='待审核';p.activity=[{at:now(),detail:'从 WORLD/TOON V0.1 导入草稿，待重新复核'}];return p;
  });
  return {...initial(),projects:imported};
 }catch{return null}
}
let data;try{let raw=JSON.parse(localStorage.getItem(APP_KEY)||'null');if(raw&&Array.isArray(raw.projects)&&Array.isArray(raw.topics))data=raw;else {data=importLegacyMetadata()||initial();legacyImport=!!data.projects.some(x=>x.id?.startsWith('legacy-'))}}catch{data=initial()}

data.characters=data.characters||[];
let ui={route:'dashboard',selected:data.projects[0]?.id||'sample-ba-zong-001',stage:0,panel:0,filter:'全部',topicFilter:'全部',search:'',reader:0,rev:0};
function persist(){try{localStorage.setItem(APP_KEY,JSON.stringify(data));if(typeof wtScheduleSync==='function')wtScheduleSync();return true}catch(err){notify('保存失败：本机存储空间可能不足，请先导出备份');return false}}
function setChange(p,desc){p.updatedAt=now();if(desc){p.activity=p.activity||[];p.activity.unshift({at:now(),detail:desc});p.activity=p.activity.slice(0,60)}persist()}
function markDirty(p){if(p.status==='已审核'||p.status==='已发布'){p.status='草稿';p.checks=Array(6).fill(false);p.reviewedAt=null;p.publishedAt=null;}setChange(p)}
const activeProjects=()=>data.projects.filter(p=>!p.deleted&&!p.archived);
function findProject(id){return data.projects.find(p=>p.id===id)}
function selected(){return findProject(ui.selected)||activeProjects()[0]||null}
function nav(route){location.hash='#/'+route;parseRoute()}
function parseRoute(){let bits=(location.hash||'#/dashboard').replace(/^#\/?/,'').split('/').filter(Boolean);ui.route=['dashboard','radar','live','characters','account','library','studio','publish','settings','reader'].includes(bits[0])?bits[0]:'dashboard';if(bits[1]&&findProject(bits[1]))ui.selected=bits[1];if(ui.route==='reader'&&bits[2])ui.reader=Math.max(0,Math.min(8,Number(bits[2])-1||0));if(ui.route==='studio'&&bits[2])ui.stage=Math.max(0,Math.min(4,Number(bits[2])||0));render()}
function link(route,id){return '#/'+route+(id?'/'+encodeURIComponent(id):'')}
function notify(msg){const x=document.querySelector('#toast');x.textContent=msg;x.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>x.classList.remove('visible'),3200)}
function statusChip(s){let color=s==='已发布'?'green':s==='待审核'?'yellow':s==='示例'?'dark':s==='已审核'?'green':'coral';return `<span class="pill ${color}">${e(s)}</span>`}
function heroHeader(k,title,lead,actions=''){return `<section class="pagehead"><div class="kicker">${k}</div><h1>${title}</h1><p class="lead">${lead}</p>${actions?`<div class="buttons" style="margin-top:20px">${actions}</div>`:''}</section>`}
function actionButton(label,act,arg='',kind=''){return `<button class="button ${kind}" data-action="${e(act)}" data-id="${e(arg)}">${label}</button>`}
function projectCard(p){let img=p.cover||p.panels?.find(x=>x.image)?.image||'';let thumb=img?`<img src="${e(img)}" alt="${e(p.title)}封面" loading="lazy">`:`<div class="placeholder-art">CP <span style="font-size:22px;margin-left:8px">${e(p.panels?.length||9)}</span></div>`;return `<article class="storycard"><a href="${link('reader',p.id)}" aria-label="阅读${e(p.title)}">${thumb}</a><div class="cardbody"><div class="buttons">${statusChip(p.status)} <span class="chip">${e(p.category)}</span></div><h3>${e(p.title)}</h3><p>${e(p.description||p.subtitle||'一部正在创作中的原创短篇。')}</p><div class="cardfoot"><span>${humanDate(p.updatedAt)} 更新 · ${p.panels?.length||9} 格</span><a href="${link('studio',p.id)}"><b>进入编辑 →</b></a></div></div></article>`}
function dashboard(){let ps=activeProjects(),pub=ps.filter(p=>p.status==='已发布').length,works=ps.filter(p=>p.status!=='已发布').length;let cards=ps.slice(0,2).map(projectCard).join('');return `<div class="hero"><div><div class="kicker">THE INDEPENDENT COMIC JOURNAL / VOL.001</div><h1>世界每日上演。<br><span>我们画下来。</span></h1><p class="lead" style="font-size:15px">一座属于你的时事漫画编辑部。从全球议题搜集到事实核查、原创改编、视觉创作与出版存档，把复杂的世界讲成好看的故事。</p><div class="buttons" style="margin-top:27px"><button class="button dark" data-action="new">＋ 开始一部新漫画</button><a href="#/library" class="button">进入漫画书架 ↗</a></div><div class="hero-meta"><div><b>${String(ps.length).padStart(2,'0')}</b><span>我的作品</span></div><div><b>${String(data.topics.length).padStart(2,'0')}</b><span>选题素材</span></div><div><b>${String(pub).padStart(2,'0')}</b><span>标记已发布</span></div></div></div><div class="hero-art"><img src="assets/cover.png" alt="《霸总的小爱情》示例漫画封面"><span class="corner">ISSUE 001 · FICTION</span></div></div><div class="sectionbar"><h2>编辑部概况 / THE DESK</h2><p>所有改动优先存于此浏览器</p></div><div class="metrics"><div class="metric"><span>活跃作品 <i>↗</i></span><strong>${ps.length}</strong><span>包含草稿和示例作品</span></div><div class="metric"><span>待完成作品 <i>↗</i></span><strong>${works}</strong><span>仍需创作与复核</span></div><div class="metric"><span>选题池 <i>↗</i></span><strong>${data.topics.length}</strong><span>手动记录的公开议题</span></div><div class="metric"><span>待审核 <i>↗</i></span><strong>${ps.filter(p=>p.status==='待审核').length}</strong><span>审核通过后才能标记发布</span></div></div><div class="sectionbar"><h2>最新作品 / RECENT ISSUES</h2><p><a href="#/library">查看全部 →</a></p></div><div class="cards3">${cards}<a class="blankcard" href="#/studio"><div class="plus">＋</div><h3>下个封面故事</h3><p>添加热点，搭建人物世界观与九格分镜，创作下一期。</p></a></div><div class="sectionbar"><h2>创作流程 / THE PIPELINE</h2></div><div class="statusflow"><div class="active">01 / 新闻选题</div><div class="active">02 / 脱敏改编</div><div class="active">03 / 剧本分镜</div><div class="active">04 / 视觉制作</div><div class="active">05 / 审核出版</div></div><div class="notice" style="margin-top:20px"><strong>重要说明：</strong>当前版本是<strong>本地优先</strong>创作与出版工具。热点需手动录入，AI 提示词可导出到外部工具使用；未接入自动新闻核验、模型生图或云端同步服务。</div>`}
function radar(){let arr=data.topics.filter(t=>ui.topicFilter==='全部'||t.stage===ui.topicFilter);arr.sort((a,b)=>topicScore(b)-topicScore(a));return `${heroHeader('02 / THE RADAR','热点素材库','不是热搜搬运，而是把值得改编的议题沉淀为可追溯选题。热度、影响和故事价值由你评分。',`<button class="button dark" data-action="topic-new">＋ 收录热点</button><a class="button" href="https://chenzhe223-tech.github.io/radar/daily/" rel="noopener noreferrer" target="_blank">查看 DAVYLAB AI Radar ↗</a>`)}<div class="notice" style="margin-top:28px">本区不会自动采集实时新闻，也不会自动证明来源真实。示例题材明确标识，发布前需要作者核验新闻原始出处和发布日期。</div><div class="toolbar"><div class="tabbar">${['全部','待核验','已核验','已转漫画'].map(x=>`<button data-action="topic-filter" data-id="${x}" class="${ui.topicFilter===x?'active':''}">${x}</button>`).join('')}</div><span class="minor">共 ${arr.length} 个选题</span></div>${arr.length?`<div class="cards2">${arr.map(t=>`<article class="box"><div class="buttons">${t.isSample?'<span class="pill dark">演示</span>':''}<span class="pill ${t.stage==='已核验'?'green':'yellow'}">${e(t.stage)}</span><span class="chip">${e(t.category)}</span></div><h3 style="margin:14px 0;font-size:21px">${e(t.title)}</h3><p class="minor">${e(t.summary||'暂无摘要')}</p><div class="buttons" style="margin:16px 0"><span class="chip">热度 ${e(t.heat)}/5</span><span class="chip">影响 ${e(t.impact)}/5</span><span class="chip">可画性 ${e(t.story)}/5</span><span class="pill dark">综合 ${topicScore(t)} / 100</span></div>${safeURL(t.source)?`<p><a href="${e(safeURL(t.source))}" target="_blank" rel="noopener noreferrer" class="reader-label">来源链接 ↗</a></p>`:''}<div class="buttons">${actionButton('改编成漫画','topic-to-project',t.id,'dark')}${actionButton('编辑','topic-edit',t.id)}${actionButton('删除','topic-delete',t.id,'danger')}</div></article>`).join('')}</div>`:`<div class="empty"><span class="icon">◎</span><b>暂无选题</b>从你关注的科技、国际与商业新闻开始记录。</div>`}`}
function topicScore(t){return Math.round((Number(t.heat||0)*.30+Number(t.impact||0)*.35+Number(t.story||0)*.35)*20)}
function library(){let ps=data.projects.filter(p=>ui.filter==='回收站'?p.deleted:!p.deleted&&(ui.filter==='全部'?true:ui.filter==='已归档'?p.archived:ui.filter==='草稿'?p.status==='草稿':p.status===ui.filter));let q=ui.search.toLowerCase().trim();if(q)ps=ps.filter(p=>[p.title,p.category,p.description].join(' ').toLowerCase().includes(q));ps.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));return `${heroHeader('03 / THE ARCHIVE','我的漫画书架','从第一部到第一百部，每篇漫画都拥有自己的素材、剧本、画面、审核和导出记录。',`<button class="button dark" data-action="new">＋ 新建作品</button>`)}<div class="toolbar"><div class="tabbar">${['全部','草稿','示例','待审核','已审核','已发布','已归档','回收站'].map(x=>`<button data-action="library-filter" data-id="${x}" class="${ui.filter===x?'active':''}">${x}</button>`).join('')}</div><input class="search" id="librarySearch" placeholder="搜索作品名称或分类" value="${e(ui.search)}" aria-label="搜索漫画作品"></div>${ps.length?`<div class="cards3">${ps.map(p=>`<div>${projectCard(p)}<div class="buttons" style="padding:9px 0 18px">${p.deleted?actionButton('恢复作品','restore',p.id,'dark'):actionButton('复制','duplicate',p.id)}${p.deleted?actionButton('彻底删除','purge',p.id,'danger'):actionButton(p.archived?'解除归档':'归档','archive',p.id)}${!p.deleted?actionButton('移入回收站','trash',p.id,'danger'):''}</div></div>`).join('')}</div>`:`<div class="empty"><b>没有符合条件的作品</b>试试其它分类，或创建一部新漫画。</div>`}`}
function studio(){let p=selected();if(!p){return `${heroHeader('04 / CREATOR STUDIO','开始创作','先创建一部漫画，进入完整五阶段编辑流程。',`<button class="button dark" data-action="new">＋ 新建作品</button>`)}`}return `${heroHeader('04 / CREATOR STUDIO','漫画创作工作台',`正在编辑：${e(p.title)} · 所有修改自动保存到此设备。`,`<a class="button" href="${link('reader',p.id)}">预览漫画 ↗</a>${actionButton('生成 AI 创作指令','prompt',p.id)}`)}<div class="editor-header" style="margin-top:22px"><div><h2>${e(p.title)}</h2><span class="minor">最后修改：${humanDate(p.updatedAt)} · ${e(p.tone)}</span></div>${statusChip(p.status)}</div><div class="stagebar">${stages.map((x,i)=>`<button data-action="studio-stage" data-id="${i}" class="${ui.stage===i?'active':''}"><strong>0${i+1}</strong>${x}</button>`).join('')}</div><div id="editorContent">${studioStage(p)}</div><div class="stepactions"><button class="button" data-action="stage-prev" ${ui.stage===0?'disabled':''}>← 上一步</button><div class="buttons">${actionButton('备份此作品','export-project',p.id)}<button class="button dark" data-action="stage-next" ${ui.stage===4?'disabled':''}>下一步 →</button></div></div>`}
function field(label,key,p,kind='input',placeholder=''){let value=e(p[key]||'');return `<div class="field ${kind==='textarea'?'wide':''}"><label for="f-${key}">${label}</label>${kind==='textarea'?`<textarea id="f-${key}" data-project-field="${key}" placeholder="${e(placeholder)}">${value}</textarea>`:`<input id="f-${key}" data-project-field="${key}" value="${value}" placeholder="${e(placeholder)}" ${kind==='date'?'type="date"':''}>`}</div>`}
function studioStage(p){if(ui.stage===0)return `<div class="work-grid"><section class="box"><div class="kicker">STEP 01 / SOURCE DESK</div><h2>故事从哪里来？</h2><p class="lead">追踪原文和时间，把“发生了什么”与“我们想怎样讲述”分开。</p><div class="fields">${field('漫画名称','title',p)}${field('副标题','subtitle',p)}<div class="field"><label>事件分类</label><select data-project-field="category">${CATS.map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>现实事件发生日期</label><input type="date" data-project-field="eventDate" value="${e(p.eventDate||'')}"></div>${field('漫画简介','description',p,'textarea','故事简介，不写未经证实的指控')}${field('现实议题名称','sourceTitle',p)}${field('可信原文链接（一行一个）','sourceURLs',p,'textarea','https://...\nhttps://...')}${field('事实核验与未知项记录','factNotes',p,'textarea','已核实事实 / 未确认之处 / 反方观点 / 日期')}</div></section><aside class="box"><h3>事实边界</h3><p class="minor">涉及现实人物的违法、隐私或情感指控时，不能只换个名字再继续影射。</p><div class="notice">至少记录一条可访问的新闻原文链接。本站<strong>不自动判断来源真伪</strong>，请人工复核。</div><a class="button" href="https://chenzhe223-tech.github.io/radar/daily/" target="_blank" rel="noopener noreferrer" style="margin-top:18px">打开 AI Radar ↗</a></aside></div>`;
if(ui.stage===1)return `<div class="work-grid"><section class="box"><div class="kicker">STEP 02 / STORY DEVELOPMENT</div><h2>把现实议题改造成好故事</h2><p class="lead">人物不是现实个人的换皮复制品。建立原创世界观、叙事角度和视觉规则。</p><div class="fields"><div class="field"><label>叙事风格</label><select data-project-field="tone">${['黑色幽默','轻喜剧','社会寓言','科幻讽刺','悬疑剧情','手绘纪实'].map(x=>`<option ${x===p.tone?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>作品形态</label><select data-project-field="format"><option>九格短篇</option><option ${p.format==='系列连载'?'selected':''}>系列连载</option></select></div>${field('虚构化改编策略','fiction',p,'textarea','时间、地点、人物身份与关联细节如何脱离真实指向？')}${field('人物设定 / 角色圣经','characters',p,'textarea','角色外貌、服装、标志动作、性格、出场关系，保证连贯性')}${field('公开展示的创作声明','disclosure',p,'textarea')}</div><div class="divider"></div><div class="buttons">${actionButton('生成九格剧情骨架（模板）','story-template',p.id,'dark')}${actionButton('复制 AI 剧本生成指令','prompt',p.id)}</div></section><aside class="box"><h3>视觉主编手记</h3><p class="minor">延续 DAVYLAB 杂志调性：克制、锐利、有戏剧张力；用跨页节奏而非堆积文字推动故事。</p><div class="notice">“自动分镜模板”是<strong>本地规则生成</strong>，并非真实 AI 接口生成，文字可继续修改。</div></aside></div>`;
if(ui.stage===2){return `<div class="box"><div class="kicker">STEP 03 / THE STORYBOARD</div><div class="editor-header"><div><h2>九格分镜脚本</h2><p class="lead">每格包含场景、画面旁白和人物对白。修改后会重置此前的审核通过状态。</p></div><div class="buttons">${actionButton('填入示例结构','story-template',p.id)}${actionButton('导出图片提示词','prompt',p.id,'dark')}</div></div><div class="panel-selector" style="grid-template-columns:repeat(9,1fr);margin-bottom:24px">${p.panels.map((a,i)=>`<button class="${ui.panel===i?'active':''}" data-action="select-panel" data-id="${i}">${a.image?`<img src="${e(a.image)}" alt="画格${i+1}" onerror="this.style.visibility='hidden'">`:'<div class="mini-placeholder"></div>'}<b>${String(i+1).padStart(2,'0')}</b></button>`).join('')}</div>${p.panels.map((a,i)=>`<div class="fields panel-script ${i===ui.panel?'':'hidden'}" data-edit-panel="${i}"><div class="field wide"><label>第 ${i+1} 格 · 标题</label><input data-panel-field="title" data-panel-index="${i}" value="${e(a.title)}"></div><div class="field wide"><label>画面描述 / 情绪 / 镜头</label><textarea data-panel-field="scene" data-panel-index="${i}">${e(a.scene)}</textarea></div><div class="field wide"><label>旁白</label><textarea data-panel-field="caption" data-panel-index="${i}">${e(a.caption)}</textarea></div><div class="field wide"><label>角色对白</label><textarea data-panel-field="dialogue" data-panel-index="${i}">${e(a.dialogue)}</textarea></div><div class="field wide"><label>画面生成 Prompt（选填）</label><textarea data-panel-field="prompt" data-panel-index="${i}">${e(a.prompt)}</textarea></div></div>`).join('')}<div class="reader-controls"><button class="button" data-action="panel-prev">← 上一格</button><b>FRAME ${ui.panel+1} / 09</b><button class="button" data-action="panel-next">下一格 →</button></div></div>`;}
if(ui.stage===3){let a=p.panels[ui.panel];return `<div class="panel-editor"><section class="box"><div class="kicker">STEP 04 / VISUAL PRODUCTION</div><h2>让每一格拥有画面</h2><p class="lead">导入自己生成或持有使用权的 PNG/JPG/WebP，已上传图片保存在浏览器 IndexedDB，不会发送到远端。</p><div class="panel-photo">${a.image?`<img src="${e(a.image)}" alt="第${ui.panel+1}格视觉素材">`:`<div class="no-photo">FRAME ${ui.panel+1}<br>尚未添加画面</div>`}</div><div class="buttons" style="margin:15px 0"><label class="button dark">↑ 上传当前画格 <input type="file" accept="image/jpeg,image/png,image/webp" data-upload-panel="${ui.panel}" hidden></label>${actionButton('复制这一格的生图 Prompt','panel-prompt',String(ui.panel))}${a.image?actionButton('移除图片','remove-image',String(ui.panel),'danger'):''}</div><div class="notice">建议统一角色特征、分镜画幅和画面配色。已有漫画示例的九张插画为独立图片。</div><div class="reader-controls"><button class="button" data-action="panel-prev">← 上一格</button><b>FRAME ${ui.panel+1} / 09</b><button class="button" data-action="panel-next">下一格 →</button></div></section><aside class="box"><h3>九格画面索引</h3><p class="minor">点选任意一格进行替换。</p><div class="panel-selector">${p.panels.map((v,i)=>`<button class="${ui.panel===i?'active':''}" data-action="select-panel" data-id="${i}">${v.image?`<img src="${e(v.image)}" alt="画格${i+1}">`:'<div class="mini-placeholder"></div>'}<b>${i+1}</b></button>`).join('')}</div><div class="divider"></div><div class="buttons">${actionButton('封面设计导出','cover-png',p.id)}</div></aside></div>`}
return `<div class="work-grid"><section class="box"><div class="kicker">STEP 05 / EDITORIAL REVIEW</div><h2>出版前最后一轮编辑</h2><p class="lead">人工核验完成之前，作品只保存在工作区。审核通过是作者的记录，不代表法律意见或事实核验系统。</p>${checksText.map((t,i)=>`<label class="checkrow"><input type="checkbox" data-check-index="${i}" ${p.checks?.[i]?'checked':''}><span>${t}</span></label>`).join('')}<div class="notice"><strong>公开声明：</strong> ${e(p.disclosure||'请先填写虚构声明。')}</div><div class="divider"></div><div class="buttons">${actionButton('进入待审核','request-review',p.id)}${actionButton('确认审稿通过','approve',p.id,'dark')}${actionButton('打开出版中心','publish-go',p.id)}</div></section><aside class="box"><h3>稿件状态</h3><p>${statusChip(p.status)}</p><p class="minor">完整画面：${p.panels.filter(a=>a.image).length}/9</p><p class="minor">核验勾选：${p.checks.filter(Boolean).length}/6</p><p class="minor">来源链接：${validSources(p).length}</p><p class="minor">历史活动：${p.activity?.length||0} 条</p><div class="divider"></div><h3>最近编辑记录</h3>${(p.activity||[]).slice(0,5).map(a=>`<div class="rowline"><div><small>${humanDate(a.at)}</small><strong>${e(a.detail)}</strong></div></div>`).join('')}</aside></div>`}
function validSources(p){return (p.sourceURLs||'').split(/\r?\n|[,，]/).map(s=>s.trim()).map(safeURL).filter(Boolean)}
function canApprove(p){let missing=[];if(!p.title.trim())missing.push('漫画标题');if(!validSources(p).length)missing.push('真实来源链接');if(!p.factNotes?.trim())missing.push('事实核验备注');if(!p.fiction?.trim())missing.push('虚构改编策略');if(!p.disclosure?.trim())missing.push('虚构声明');if(!p.checks?.every(Boolean))missing.push('6 项人工核查');if(p.panels.filter(a=>a.image).length!==9)missing.push('九格画面');return missing}
function reader(){let p=selected();if(!p)return `<div class="empty">作品不存在。<a href="#/library">返回书架</a></div>`;let idx=ui.reader,a=p.panels[idx],imgs=p.panels;return `${heroHeader('THE READING ROOM / ISSUE',e(p.title),e(p.subtitle||p.description||'原创漫画作品'),`<a class="button" href="${link('library')}">← 回到书架</a>${actionButton('编辑此作','edit',p.id)}${actionButton('下载九格封面','cover-png',p.id)}`)}<div class="reader-layout" style="margin-top:24px"><div><div class="reader-image">${a.image?`<img src="${e(a.image)}" alt="第${idx+1}格：${e(a.scene)}">`:`<div class="no-photo" style="color:#eee">第 ${idx+1} 格 · 尚未上传画面</div>`}</div><div class="reader-controls"><button class="button" data-action="reader-prev">← 上一格</button><b>0${idx+1} / 09</b><button class="button dark" data-action="reader-next">下一格 →</button></div><div class="box"><div class="kicker">FRAME ${idx+1} / ${e(a.title)}</div><p>${e(a.caption)}</p><p class="minor">${e(a.dialogue)}</p></div></div><aside><div class="reader-thumbbar">${imgs.map((im,i)=>`<button class="${i===idx?'active':''}" data-action="reader-jump" data-id="${i}" aria-label="第${i+1}格">${im.image?`<img src="${e(im.image)}" alt="第${i+1}格">`:`<span>${i+1}</span>`}</button>`).join('')}</div><div class="notice" style="margin-top:20px">${e(p.disclosure)}</div></aside></div>`}
function publish(){let ps=activeProjects();let p=selected();return `${heroHeader('05 / THE PRESS','出版与分发中心','一份作品，多种出口：九张漫画图片、封面海报、离线阅读网站、创作备份及可复制的社交文案。',`<a class="button" href="#/studio">前往编辑工作台 ↗</a>`)}<div class="work-grid" style="margin-top:27px"><section class="box"><div class="kicker">SELECT THE ISSUE</div><h2>选择准备出版的漫画</h2><div class="field"><label>当前作品</label><select id="publishProject">${ps.map(x=>`<option value="${e(x.id)}" ${p?.id===x.id?'selected':''}>${e(x.title)} · ${e(x.status)}</option>`).join('')}</select></div>${p?`<div class="rowline" style="margin:16px 0"><div><strong>${e(p.title)}</strong><small>${p.panels.filter(a=>a.image).length}/9 张视觉素材 · ${p.checks.filter(Boolean).length}/6 项审核</small></div>${statusChip(p.status)}</div><div class="notice">${p.status==='已审核'||p.status==='已发布'?'该稿件已通过本地人工审核，可标记发布及导出正式素材。':`尚未审核完成：${e(canApprove(p).slice(0,3).join('、')||'请人工检查')}${canApprove(p).length>3?'等':''}。允许导出个人预览，但公开发布前请完成审校。`}</div><div class="sectionbar"><h2>出版动作</h2></div><div class="cards2"><div class="outline"><h3>01 / 漫画图片 ZIP</h3><p class="minor">九张图片、作品介绍和创作声明，适合微信和小红书。缺失画面时导出失败。</p>${actionButton('打包九张 PNG/JPG','zip-pages',p.id,'dark')}</div><div class="outline"><h3>02 / 离线漫画网站</h3><p class="minor">生成无需后台的完整 HTML 漫画阅读包，可部署到静态站点。</p>${actionButton('导出静态发布包','zip-site',p.id,'dark')}</div><div class="outline"><h3>03 / 杂志式封面</h3><p class="minor">1080 × 1440 的原创排版 PNG，独立封面不包含九宫格细字。</p>${actionButton('生成封面 PNG','cover-png',p.id)}</div><div class="outline"><h3>04 / 作品编辑备份</h3><p class="minor">JSON 格式保存设定、分镜、来源、审核记录（不含上传图片）。</p>${actionButton('下载项目 JSON','export-project',p.id)}</div></div><div class="divider"></div><div class="buttons">${actionButton('复制公众号简介','copy-social',p.id)}${actionButton('复制九格 AI 生图指令','prompt',p.id)}${actionButton('标记已发布','mark-published',p.id,'coral')}</div>`:''}</section><aside class="box"><h3>出版规则</h3><div class="outlined-list"><div class="rowline"><div><strong>新闻 ≠ 漫画剧情</strong><small>原创改编需要可见的虚构标注</small></div></div><div class="rowline"><div><strong>自动化 ≠ 已上线</strong><small>本机标记不代表网站或社交平台实际发布</small></div></div><div class="rowline"><div><strong>图片必须有使用权</strong><small>自行生成或获得合法授权</small></div></div><div class="rowline"><div><strong>PDF 输出</strong><small>在离线漫画网站中选择浏览器“打印 → 保存为 PDF”</small></div></div></div><div class="notice" style="margin-top:18px">当前<strong>没有微信 / 小红书账户直发接口</strong>。本页面提供素材下载，不会擅自替你向公众发布。</div></aside></div>`}
function settings(){return `${heroHeader('06 / YOUR WORKSPACE','数据与偏好','让漫画资产属于你。保存于本机的作品可以导出备份，换浏览器或清除站点数据前务必操作。')}<div class="cards2" style="margin-top:28px"><section class="box"><h3>作品数据库备份</h3><p class="minor">导出 ZIP，包含全部项目、热点记录、审稿元数据和已上传图片。内置示例图片也会打包。</p><div class="buttons">${actionButton('导出完整工作区 ZIP','backup-all','','dark')}<label class="button">导入 ZIP 备份<input type="file" data-import-workspace accept=".zip,application/zip" hidden></label></div><p class="risk">导入操作会替换当前工作区，请先导出当前版本备份。</p></section><section class="box"><h3>管理原则</h3><p class="minor">不上传新闻原文和图片到任何云端。跨设备同步、账号体系、定时热点采集和真实模型创作尚未接通。</p><div class="buttons"><a class="button" href="#/library">作品回收站 →</a>${actionButton('清空本机所有数据','reset-all','','danger')}</div></section><section class="box"><h3>数据使用说明</h3><p class="minor">漫画信息、来源、状态：localStorage；上传的图片：IndexedDB。浏览器清理缓存或无痕模式可能抹掉数据。本地备份是当前版本的可靠迁移方式。</p><p class="minor">最大单张导入图片：12MB · 支持 JPEG、PNG、WebP。</p></section><section class="box"><h3>平台进度</h3><div class="rowline"><strong>本地编辑 / 九格管理 / 作品归档</strong><span class="pill green">已实现</span></div><div class="rowline"><strong>发布素材与网页导出</strong><span class="pill green">已实现</span></div><div class="rowline"><strong>AI 新闻自动抓取与核验</strong><span class="pill yellow">未接入</span></div><div class="rowline"><strong>自动 AI 生图及云端同步</strong><span class="pill yellow">未接入</span></div></section></div>`}
function render(){document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===ui.route));const title={live:'全球热点',characters:'角色档案',account:'云端账户',dashboard:'总览',radar:'热点素材',library:'漫画书架',studio:'创作工作台',publish:'出版中心',settings:'数据管理',reader:'漫画阅读'};document.querySelector('#crumb').textContent=title[ui.route];let fn={dashboard,radar,live:wtLive,characters:wtCharacters,account:wtAccount,library,studio,publish,settings,reader}[ui.route];document.querySelector('#view').innerHTML=fn();document.title=`${title[ui.route]} — WORLD/TOON · By DAVYLAB`;document.querySelector('.rail').classList.remove('is-open')}
function modal(body){let root=document.querySelector('#modalRoot');root.innerHTML=`<div class="modal-card"><button class="iconbtn modal-close" data-action="modal-close" aria-label="关闭">×</button>${body}</div>`;root.hidden=false}
function closeModal(){let x=document.querySelector('#modalRoot');x.hidden=true;x.innerHTML=''}
function newProject(topic){let p=emptyProject(topic);data.projects.unshift(p);ui.selected=p.id;ui.stage=0;persist();closeModal();nav(`studio/${p.id}/0`);notify('已创建独立作品草稿')}
function topicModal(t){modal(`<div class="kicker">NEW EDITORIAL LEAD</div><h2>${t?'编辑热点':'添加一个热点'}</h2><p class="minor">手工记录可信来源。评分是个人策划评分，不代表真实平台流量。</p><form id="topicForm" data-id="${e(t?.id||'')}"><div class="fields"><div class="field wide"><label>事件标题 *</label><input name="title" required maxlength="180" value="${e(t?.title||'')}"></div><div class="field"><label>类别</label><select name="category">${CATS.map(x=>`<option ${x===t?.category?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>核验状态</label><select name="stage">${['待核验','已核验','已转漫画'].map(x=>`<option ${x===t?.stage?'selected':''}>${x}</option>`).join('')}</select></div><div class="field wide"><label>新闻摘要</label><textarea name="summary">${e(t?.summary||'')}</textarea></div><div class="field wide"><label>原始来源链接</label><input type="url" name="source" placeholder="https://..." value="${e(t?.source||'')}"></div>${['heat','impact','story'].map((k,i)=>`<div class="field"><label>${['热度','影响力','漫画价值'][i]}（1—5）</label><input name="${k}" type="number" min="1" max="5" value="${e(t?.[k]||3)}"></div>`).join('')}</div><div class="stepactions"><button type="button" class="button" data-action="modal-close">取消</button><button class="button dark" type="submit">保存选题</button></div></form>`)}
function saveTopic(form){let values=Object.fromEntries(new FormData(form).entries());let title=(values.title||'').trim();if(!title){notify('请填写热点标题');return}if(values.source&&!safeURL(values.source)){notify('来源链接必须为完整 HTTP(S) 地址');return}let t=data.topics.find(t=>t.id===form.dataset.id);if(!t){t={id:uid(),createdAt:now()};data.topics.unshift(t)}Object.assign(t,{...values,title,heat:Math.max(1,Math.min(5,Number(values.heat)||1)),impact:Math.max(1,Math.min(5,Number(values.impact)||1)),story:Math.max(1,Math.min(5,Number(values.story)||1)),isSample:false});persist();closeModal();render();notify('选题已保存')}
function makePrompt(p,index){const lead=`你是 DAVYLAB WORLD/TOON 的原创漫画编剧与视觉导演。请基于以下内容创作，但必须将新闻可验证事实与虚构情节清晰区分，绝不编造针对现实人物的违法、私人关系或交易事实。风格：高级杂志审美、克制黑色幽默、清晰分镜、角色服饰和面貌连续一致；任何原始新闻报道不应被照搬。\n\n漫画标题：${p.title}\n故事摘要：${p.description}\n现实选题：${p.sourceTitle}\n可信来源：${p.sourceURLs||'未提供，必须先核验'}\n已核查事实：${p.factNotes||'待核验'}\n虚构改编策略：${p.fiction||'待补全'}\n角色圣经：${p.characters||'待补全'}\n公开声明：${p.disclosure}\n\n`;
if(index!==undefined){let a=p.panels[index];return lead+`请为第 ${index+1} 格生成一张竖版漫画视觉，无水印，不需要生成可读中文字，预留旁白/对白文字排版空间。人物与全书风格一致。\n镜头：${a.scene}\n旁白：${a.caption}\n对白：${a.dialogue}\n额外视觉提示：${a.prompt}`;}
return lead+'请输出 9 格原创漫画分镜表，每格列出：标题、主体人物、画面构图、光线/配色、旁白、对白、独立画面提示词。尊重虚构声明；有事实不确定性时标注“待核验”，不可强行填空。\n\n已有分镜：\n'+p.panels.map((a,i)=>`#${i+1} ${a.title}\n画面：${a.scene}\n旁白：${a.caption}\n对白：${a.dialogue}`).join('\n');}
async function copyText(str){try{await navigator.clipboard.writeText(str);notify('内容已复制到剪贴板')}catch{modal(`<h2>复制内容</h2><p class="minor">此浏览器无法直接复制，请手动选取下面文本。</p><textarea style="width:100%;min-height:280px" readonly>${e(str)}</textarea>`);}}
function fillStoryTemplate(p){if(p.panels.some(a=>a.scene.trim())&&!confirm('将用九格通用叙事模板填充全部画面描述（不影响已上传图片），继续吗？'))return;let titles=['引子：平静表面','转折：不速之客','追问：各方说法','升级：风暴扩散','抉择：进退两难','公开：聚光灯下','反差：旁观者说','反转：重新定义','余韵：留给读者'];p.panels.forEach((a,i)=>{a.title=titles[i];a.scene=`原创漫画画面：第${i+1}幕。围绕「${p.sourceTitle||p.title}」的公共议题，以原创虚构角色展开。镜头与场景应体现${['平静','冲突','秘密','变化','挣扎','对峙','讽刺','反转','余味'][i]}，避免与真实人物发生可识别对应。`;a.caption=['故事从一个日常瞬间开始。','突然，事件打破宁静。','每个人都在讲述自己的版本。','局势朝着意外的方向发展。','主角必须作出选择。','聚光灯照亮了另一面。','旁观者发现事情并不简单。','原来的答案被重新书写。','未完待续，世界仍在继续。'][i];a.dialogue='';a.prompt='';});markDirty(p);setChange(p,'应用九格叙事模板');render();notify('已生成九格剧情骨架（本地模板）')}
async function openDB(){return new Promise((res,rej)=>{if(!('indexedDB' in window))return rej(Error('浏览器不支持 IndexedDB'));let req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore('media');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
let dbPromise;const db=()=>dbPromise||(dbPromise=openDB());
async function putMedia(key,blob){let d=await db();return new Promise((resolve,reject)=>{let tx=d.transaction('media','readwrite');tx.objectStore('media').put(blob,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function getMedia(key){let d=await db();return new Promise((resolve,reject)=>{let req=d.transaction('media').objectStore('media').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function delMedia(key){let d=await db();return new Promise((resolve,reject)=>{let tx=d.transaction('media','readwrite');tx.objectStore('media').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
const objectURLs=new Map();async function resolveImage(s){if(!s)return '';if(!s.startsWith('media:'))return s;if(objectURLs.has(s))return objectURLs.get(s);let blob=await getMedia(s.slice(6));if(!blob&&typeof wtDownloadMedia==='function'){blob=await wtDownloadMedia(s.slice(6));if(blob)await putMedia(s.slice(6),blob)}if(!blob)return '';let url=URL.createObjectURL(blob);objectURLs.set(s,url);return url}
async function hydrateImages(){let imgs=[...document.querySelectorAll('img[data-source]')];for(let el of imgs){try{let url=await resolveImage(el.dataset.source);if(el.isConnected)el.src=url||''}catch{if(el.isConnected)el.alt='图片读取失败，请从备份恢复'}}}
function mediaSrc(s){return s?.startsWith('media:')?'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100" fill="#d7ddcf"/><text x="20" y="53" font-size="12">加载中</text></svg>'):s||''}
// Resolve any image references that were uploaded and live in IndexedDB.
const originalRender=render;render=function(){originalRender();document.querySelectorAll('img').forEach(el=>{if(el.hasAttribute('src')&&el.getAttribute('src').startsWith('media:')){el.dataset.source=el.getAttribute('src');el.src=mediaSrc(el.dataset.source)}});hydrateImages()};
async function uploadPanel(input){let file=input.files?.[0];if(!file)return;let type=file.type;if(!['image/jpeg','image/png','image/webp'].includes(type)){notify('仅支持 JPG、PNG、WebP 图片');return}if(file.size>12*1024*1024){notify('单张图片不能超过 12 MB');return}let p=selected(),i=Number(input.dataset.uploadPanel);let img=p.panels[i];let key=uid();try{await putMedia(key,file);let old=img.image;img.image='media:'+key;if(old?.startsWith('media:'))await delMedia(old.slice(6));markDirty(p);setChange(p,`更新第${i+1}格画面`);render();notify('图片已保存；登录后可同步到私有云端')}catch(err){notify('图片写入失败：'+err.message)}}
function saveFile(blob,filename){let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
async function getImageBlob(img){if(img.startsWith('media:')){let b=await getMedia(img.slice(6));if(!b&&typeof wtDownloadMedia==='function'){b=await wtDownloadMedia(img.slice(6));if(b)await putMedia(img.slice(6),b)}if(!b)throw Error('找不到已上传图片：'+img);return b}if(!img)throw Error('有画格尚未上传图片');let resp=await fetch(img);if(!resp.ok)throw Error('无法读取图片 '+img);return resp.blob()}
function contentExt(blob){return blob.type==='image/webp'?'webp':blob.type==='image/jpeg'?'jpg':'png'}
// A deterministic, dependency-free ZIP (STORE method), readable by Windows/macOS/7-Zip.
const enc=new TextEncoder(),dec=new TextDecoder();
const concat=xs=>{let n=xs.reduce((t,b)=>t+b.length,0),out=new Uint8Array(n),off=0;for(let a of xs){out.set(a,off);off+=a.length}return out};
let crcTable;function crc32(buf){if(!crcTable)crcTable=Array.from({length:256},(_,i)=>{let c=i;for(let j=0;j<8;j++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);return c>>>0});let c=0xffffffff;for(let b of buf)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function packZip(entries){let parts=[],central=[],offset=0;for(let {name,bytes} of entries){let path=enc.encode(name),body=bytes instanceof Uint8Array?bytes:enc.encode(bytes),sum=crc32(body);let local=new Uint8Array(30+path.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint16(8,0,true);v.setUint32(14,sum,true);v.setUint32(18,body.length,true);v.setUint32(22,body.length,true);v.setUint16(26,path.length,true);local.set(path,30);parts.push(local,body);
let c=new Uint8Array(46+path.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x0800,true);d.setUint32(16,sum,true);d.setUint32(20,body.length,true);d.setUint32(24,body.length,true);d.setUint16(28,path.length,true);d.setUint32(42,offset,true);c.set(path,46);central.push(c);offset+=local.length+body.length}let center=concat(central);let end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,center.length,true);v.setUint32(16,offset,true);return new Blob([...parts,center,end],{type:'application/zip'})}
function readZip(bytes){let u=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes),v=new DataView(u.buffer,u.byteOffset,u.byteLength),pos=0,found=new Map();while(pos+30<=u.length&&v.getUint32(pos,true)===0x04034b50){let method=v.getUint16(pos+8,true),size=v.getUint32(pos+18,true),nameLen=v.getUint16(pos+26,true),extra=v.getUint16(pos+28,true),name=dec.decode(u.slice(pos+30,pos+30+nameLen)),at=pos+30+nameLen+extra;if(method!==0)throw Error('只支持本平台导出的 ZIP 原始存储格式');if(at+size>u.length)throw Error('ZIP 文件损坏');if(name.includes('..')||name.startsWith('/'))throw Error('ZIP 文件路径无效');found.set(name,u.slice(at,at+size));pos=at+size}if(!found.size)throw Error('未找到可读的 ZIP 条目');return found}
const blobBytes=async b=>new Uint8Array(await b.arrayBuffer());
async function collectImages(p,filenames='pages'){let entries=[],images=[];for(let i=0;i<p.panels.length;i++){let img=p.panels[i].image;if(!img)throw Error(`第 ${i+1} 格尚未上传画面`);let b=await getImageBlob(img);let filename=`${filenames}/page-${String(i+1).padStart(2,'0')}.${contentExt(b)}`;entries.push({name:filename,bytes:await blobBytes(b)});images.push(filename)}return {entries,images}}
function escapeScript(s){return JSON.stringify(s).replace(/</g,'\\u003c')}
function generateReaderHTML(p,imgs){let payload={title:p.title,subtitle:p.subtitle,description:p.description,disclosure:p.disclosure,panels:p.panels.map((a,i)=>({title:a.title,caption:a.caption,dialogue:a.dialogue,image:imgs[i]}))};let json=escapeScript(payload);return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(p.title)} · By DAVYLAB</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f0e8;color:#1d2520;font-family:system-ui,'Noto Sans SC',sans-serif}header{text-align:center;padding:36px 14px 25px}small{letter-spacing:2px;color:#d3634e}h1{font-family:Georgia,serif;font-size:clamp(35px,7vw,64px);margin:12px 0}main{max-width:850px;margin:auto;padding:15px}figure{margin:0 0 40px;background:#fff;padding:14px;border:1px solid #ded9d0;break-inside:avoid;page-break-inside:avoid}img{max-width:100%;display:block;margin:auto;max-height:85vh;object-fit:contain}figcaption{padding:15px 8px;line-height:1.7}b{font-size:13px}.muted{color:#6f766d;font-size:13px}footer{padding:30px;text-align:center;color:#747b72;font-size:12px;border-top:1px solid #ddd}button{background:#1d2520;color:white;border:0;padding:12px 20px;cursor:pointer;border-radius:5px}@media print{button{display:none}figure{break-after:page;page-break-after:always;margin:0}header{padding:10px}footer{display:none}}</style></head><body><header><small>DAVYLAB / WORLD/TOON · ORIGINAL FICTION</small><h1>${e(p.title)}</h1><p>${e(p.subtitle||p.description)}</p><button onclick="window.print()">打印 / 保存为 PDF</button></header><main id="pages"></main><footer>${e(p.disclosure)}<p>By DAVYLAB · 独立原创漫画</p></footer><script>let d=${json};const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));document.getElementById('pages').innerHTML=d.panels.map((p,i)=>'<figure><img src="'+p.image+'" alt="画格'+(i+1)+'"><figcaption><b>FRAME '+String(i+1).padStart(2,'0')+' · '+esc(p.title)+'</b><p>'+esc(p.caption)+'</p><p class="muted">'+esc(p.dialogue)+'</p></figcaption></figure>').join('');<\/script></body></html>`}
async function exportZip(p,mode){notify('正在整理漫画文件…');try{let {entries,images}=await collectImages(p);if(mode==='site'){entries.push({name:'index.html',bytes:enc.encode(generateReaderHTML(p,images))});entries.push({name:'README.txt',bytes:enc.encode('DAVYLAB WORLD/TOON\n解压 ZIP 后打开 index.html 即可离线阅读。\n在浏览器中选择“打印”可保存为 PDF。\n本包未自动发布到任何在线网站。')})}else{entries.push({name:'作品说明.txt',bytes:enc.encode(`${p.title}\n${p.subtitle}\n\n${p.description}\n\n${p.disclosure}\n\nBy DAVYLAB`)})}saveFile(packZip(entries),safeName(p.title)+(mode==='site'?'_离线漫画网站.zip':'_九张漫画图片.zip'));setChange(p,`导出${mode==='site'?'离线网站':'九格漫画'}素材`);notify('打包完成，已触发浏览器下载')}catch(err){notify('导出未完成：'+err.message)}}
function canvasRound(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
async function exportCover(p){notify('正在绘制封面…');try{let canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1440;let ctx=canvas.getContext('2d');ctx.fillStyle='#f1eee5';ctx.fillRect(0,0,1080,1440);ctx.fillStyle='#202622';ctx.fillRect(0,0,1080,175);ctx.fillStyle='#ffffff';ctx.font='bold 67px Georgia, serif';ctx.fillText('WORLD/TOON',60,97);ctx.fillStyle='#dc694e';ctx.font='bold 22px sans-serif';ctx.fillText('BY DAVYLAB  /  ORIGINAL STORIES',62,139);ctx.fillStyle='#1d2520';ctx.font='bold 27px sans-serif';ctx.fillText('THE WORLD, REIMAGINED IN PANELS.',63,230);
let source=p.cover||p.panels.find(a=>a.image)?.image||'';if(!source){ctx.fillStyle='#d7ddcf';ctx.fillRect(62,270,956,795);ctx.fillStyle='#4b5e53';ctx.font='bold 110px Georgia,serif';ctx.fillText('STORY',112,680);ctx.fillText('IN PROGRESS',112,800,830)}else{let b=await getImageBlob(source);let u=URL.createObjectURL(b);try{let img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=u});let x=62,y=270,w=956,h=795;let scale=Math.max(w/img.width,h/img.height);ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.drawImage(img,x+(w-img.width*scale)/2,y+(h-img.height*scale)/2,img.width*scale,img.height*scale);ctx.restore()}finally{URL.revokeObjectURL(u)}}
ctx.fillStyle='#202622';ctx.fillRect(62,1080,956,288);ctx.fillStyle='#f6f0e7';ctx.font='bold 66px "Noto Sans SC",sans-serif';let title=p.title.slice(0,13);ctx.fillText(title,98,1182,890);ctx.fillStyle='#bac2b8';ctx.font='27px sans-serif';ctx.fillText((p.subtitle||p.description||'一部原创漫画').slice(0,36),100,1243,880);ctx.fillStyle='#de7054';ctx.fillRect(99,1282,130,5);ctx.fillStyle='#bfc8bd';ctx.font='18px sans-serif';ctx.fillText('DAVYLAB WORLD/TOON  /  FICTIONAL ADAPTATION',101,1322);let blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error('封面渲染失败');saveFile(blob,safeName(p.title)+'_杂志封面.png');notify('封面已生成：1080×1440 PNG')}catch(err){notify('封面生成失败：'+err.message)}}
function exportProject(p){saveFile(new Blob([JSON.stringify({schema:'comicpress-project-v2',project:p},null,2)],{type:'application/json'}),safeName(p.title)+'_项目数据.json');notify('项目 JSON 已导出，不含上传图片')}
async function backupAll(){notify('正在创建完整备份，请勿关闭此页');try{let items=[{name:'workspace.json',bytes:enc.encode(JSON.stringify({schema:'comicpress-backup-v2',exportedAt:now(),data}))}],seen=new Set();for(let p of data.projects){let imgs=[...(p.panels||[]).map(a=>a.image),p.cover];for(let im of imgs){if(!im||seen.has(im))continue;seen.add(im);let b=await getImageBlob(im);let name=im.startsWith('media:')?`media/${im.slice(6)}.${contentExt(b)}`:`seed/${im.replace('assets/','')}`;items.push({name,bytes:await blobBytes(b)})}}saveFile(packZip(items),'DAVYLAB_Comic_Press_完整备份_'+new Date().toISOString().slice(0,10)+'.zip');notify('完整 ZIP 备份已生成')}catch(err){notify('备份失败：'+err.message)}}
async function importWorkspace(file){if(!confirm('导入将覆盖本机全部漫画资料。建议先导出当前备份。继续吗？'))return;notify('正在验证并恢复备份…');try{let files=readZip(new Uint8Array(await file.arrayBuffer())),raw=files.get('workspace.json');if(!raw)throw Error('不是本平台的完整备份');let obj=JSON.parse(dec.decode(raw));if(obj.schema!=='comicpress-backup-v2'||!Array.isArray(obj.data?.projects)||!Array.isArray(obj.data?.topics))throw Error('工作区数据格式不符合要求');let fresh=obj.data;for(let p of fresh.projects){if(!Array.isArray(p.panels)||p.panels.length!==9)throw Error('备份中存在损坏的九格作品');for(let a of [...p.panels,{image:p.cover}]){let im=a.image;if(!im)continue;if(im.startsWith('media:')){let k=im.slice(6),name=[...files.keys()].find(n=>n.startsWith(`media/${k}.`));if(!name)throw Error('备份缺失图片 '+k);let mime=name.endsWith('.webp')?'image/webp':name.endsWith('.jpg')?'image/jpeg':'image/png';await putMedia(k,new Blob([files.get(name)],{type:mime}))}else if(im.startsWith('assets/')){if(!files.has('seed/'+im.slice(7)))throw Error('备份缺失示例素材 '+im)}}}data=fresh;persist();ui.selected=data.projects[0]?.id||'';closeModal();nav('library');notify('完整工作区已恢复，请核对作品')}catch(err){notify('导入失败：'+err.message)}}
async function action(act,id){let p=selected();switch(act){case 'new':newProject();break;case 'topic-new':topicModal();break;case 'topic-edit':topicModal(data.topics.find(t=>t.id===id));break;case 'topic-filter':ui.topicFilter=id;render();break;case 'topic-delete':if(confirm('确定移除此选题吗？')){data.topics=data.topics.filter(t=>t.id!==id);persist();render()}break;case 'topic-to-project':{let t=data.topics.find(t=>t.id===id);if(!t)break;t.stage='已转漫画';persist();newProject(t);break}case 'library-filter':ui.filter=id;render();break;case 'edit':ui.selected=id;ui.stage=0;nav(`studio/${id}/0`);break;case 'duplicate':{let orig=findProject(id);if(!orig)break;let v=structuredClone(orig);v.id=uid();v.title+=' · 副本';v.status='草稿';v.checks=Array(6).fill(false);v.deleted=false;v.archived=false;v.createdAt=now();v.updatedAt=now();v.activity=[{at:now(),detail:'复制自「'+orig.title+'」'}];data.projects.unshift(v);persist();render();notify('已复制作品')}break;case 'archive':{let v=findProject(id);v.archived=!v.archived;setChange(v,v.archived?'归档作品':'解除归档');render();break}case 'trash':if(confirm('将此作品移入回收站？可从回收站恢复。')){let v=findProject(id);v.deleted=true;setChange(v,'移入回收站');render()}break;case 'restore':{let v=findProject(id);v.deleted=false;v.archived=false;setChange(v,'恢复作品');render();break}case 'purge':if(confirm('彻底删除此作品？不能从回收站恢复，请先备份。')){data.projects=data.projects.filter(v=>v.id!==id);persist();render()}break;case 'studio-stage':ui.stage=Number(id);render();break;case 'stage-prev':ui.stage=Math.max(0,ui.stage-1);render();break;case 'stage-next':ui.stage=Math.min(4,ui.stage+1);render();break;case 'select-panel':ui.panel=Number(id);render();break;case 'panel-prev':ui.panel=(ui.panel+8)%9;render();break;case 'panel-next':ui.panel=(ui.panel+1)%9;render();break;case 'reader-prev':ui.reader=(ui.reader+8)%9;render();break;case 'reader-next':ui.reader=(ui.reader+1)%9;render();break;case 'reader-jump':ui.reader=Number(id);render();break;case 'story-template':fillStoryTemplate(findProject(id)||p);break;case 'prompt':copyText(makePrompt(findProject(id)||p));break;case 'panel-prompt':copyText(makePrompt(p,Number(id)));break;case 'remove-image':if(confirm('移除这一格的图片？上传素材会从浏览器媒体库删除。')){let a=p.panels[Number(id)],old=a.image;a.image='';if(old.startsWith('media:'))await delMedia(old.slice(6));markDirty(p);setChange(p,'移除图片');render()}break;case 'request-review':p.status='待审核';setChange(p,'提交待审核');render();break;case 'approve':{let missing=canApprove(p);if(missing.length){notify('无法审核通过：缺少 '+missing.join('、'));return}p.status='已审核';p.reviewedAt=now();setChange(p,'作者人工审核通过');render();notify('已审核通过（本地记录）');break}case 'mark-published':{let v=findProject(id);if(v.status!=='已审核'){notify('请先在创作台完成全部审核，再标记发布');return}if(!confirm('这只会记录你的发布状态，不会直接发布到网络。确认已完成对外发布？'))return;v.status='已发布';v.publishedAt=now();setChange(v,'记录作品已发布（人工确认）');render();notify('已记录发布状态，未执行网络上传');break}case 'publish-go':ui.selected=id;nav('publish');break;case 'export-project':exportProject(findProject(id));break;case 'zip-pages':await exportZip(findProject(id),'pages');break;case 'zip-site':await exportZip(findProject(id),'site');break;case 'cover-png':await exportCover(findProject(id));break;case 'copy-social':{let v=findProject(id);copyText(`《${v.title}》\n${v.subtitle||v.description}\n\n九格看世界，幽默不失锋芒。\n${v.disclosure}\n\nWORLD/TOON · By DAVYLAB`);break}case 'backup-all':await backupAll();break;case 'reset-all':{if(!confirm('彻底清空本机全部漫画作品和选题？操作不可撤销。'))return;if(!confirm('请确认已下载完整备份。仍然清空？'))return;data=initial();persist();ui.selected=data.projects[0].id;nav('dashboard');notify('已重置工作区（图片可能仍占用媒体缓存）');break}case 'modal-close':closeModal();break;default:console.warn('unknown action',act)}}
document.addEventListener('click',ev=>{const anchor=ev.target.closest('a[href^="#/"]');if(anchor){ev.preventDefault();nav(anchor.getAttribute('href').slice(2));return}let t=ev.target.closest('[data-action]');if(t){ev.preventDefault();action(t.dataset.action,t.dataset.id||'').catch(err=>notify('操作未完成：'+err.message))}});
document.addEventListener('submit',ev=>{if(ev.target.id==='topicForm'){ev.preventDefault();saveTopic(ev.target)}});
document.addEventListener('input',ev=>{let el=ev.target,p=selected();if(el.matches('[data-project-field]')&&p){p[el.dataset.projectField]=el.value;markDirty(p);return}if(el.matches('[data-panel-field]')&&p){let idx=Number(el.dataset.panelIndex);p.panels[idx][el.dataset.panelField]=el.value;markDirty(p);return}if(el.id==='librarySearch'){ui.search=el.value;let caret=el.selectionStart;render();let next=document.querySelector('#librarySearch');next?.focus();next?.setSelectionRange(caret,caret)}});
document.addEventListener('change',ev=>{let el=ev.target,p=selected();if(el.matches('[data-check-index]')&&p){p.checks[Number(el.dataset.checkIndex)]=el.checked;if(!el.checked&&p.status==='已审核')p.status='草稿';setChange(p);render()}if(el.matches('[data-upload-panel]'))uploadPanel(el).then(()=>{if(typeof wtScheduleSync==='function')wtScheduleSync()});if(el.matches('[data-import-workspace]')&&el.files[0])importWorkspace(el.files[0]);if(el.id==='publishProject'){ui.selected=el.value;render()}if(el.matches('[data-project-field]')&&p){setChange(p,'更新作品设定')}});
document.getElementById('topNew').addEventListener('click',()=>newProject());document.getElementById('menuToggle').addEventListener('click',()=>document.querySelector('.rail').classList.toggle('is-open'));
window.addEventListener('hashchange',parseRoute);document.addEventListener('keydown',ev=>{if(document.querySelector('#modalRoot:not([hidden])')){if(ev.key==='Escape')closeModal();return}if(ui.route==='reader'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){if(ev.key==='ArrowRight'){ui.reader=(ui.reader+1)%9;render()}if(ev.key==='ArrowLeft'){ui.reader=(ui.reader+8)%9;render()}}});
async function finishLegacyImport(){
 let moved=0,failed=0;
 for(let p of data.projects){for(let im of p.panels){if(im.image?.startsWith('data:image/')){
  try{const b=await(await fetch(im.image)).blob(),key=uid();await putMedia(key,b);im.image='media:'+key;moved++}catch{failed++}
 }}}
 if(failed){notify(`旧版导入存在 ${failed} 张图片迁移失败；请先在旧版导出备份`);return}
 if(persist()){legacyImport=false;notify(`旧版作品已导入，${moved} 张图片转入安全媒体存储`);render()}
}
if(legacyImport)finishLegacyImport();else if(!localStorage.getItem(APP_KEY))persist();parseRoute();
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});